from __future__ import annotations

import pytest

from idac.ops import OperationContext, payload_from_model
from idac.ops.families import search
from idac.ops.runtime import IdaOperationError, IdaRuntime, SegmentRange


def _op_strings(runtime: IdaRuntime, params: dict[str, object]):
    """Parse and run the `strings` operation the way production dispatch does."""
    request = search._parse_strings(params)
    return payload_from_model(search._strings(OperationContext(runtime=runtime), request))


class _FakeIdaBytes:
    HEAD = 0x1
    STRLIT = 0x2
    ALOPT_IGNHEADS = 0x1

    def __init__(
        self,
        items: dict[int, tuple[int, int, bytes]],
        *,
        scan_lengths: dict[int, int] | None = None,
    ) -> None:
        self._items = items
        self._heads = sorted(items)
        self._scan_lengths = {} if scan_lengths is None else scan_lengths

    def get_flags(self, ea: int) -> int:
        item = self._items.get(ea)
        if item is None:
            return 0
        _strtype, _length, _text = item
        return self.HEAD | self.STRLIT

    @staticmethod
    def is_head(flags: int) -> bool:
        return bool(flags & _FakeIdaBytes.HEAD)

    @staticmethod
    def is_strlit(flags: int) -> bool:
        return bool(flags & _FakeIdaBytes.STRLIT)

    def next_head(self, ea: int, end: int) -> int:
        for head in self._heads:
            if head > ea and head < end:
                return head
        return -1

    def get_item_end(self, ea: int) -> int:
        _strtype, length, _text = self._items[ea]
        return ea + length

    def get_strlit_contents(self, ea: int, length: int, strtype: int) -> bytes:
        expected_strtype, expected_length, text = self._items[ea]
        assert strtype == expected_strtype
        assert length == expected_length
        return text

    def get_max_strlit_length(self, ea: int, strtype: int, options: int = 0) -> int:
        _ = (strtype, options)
        return self._scan_lengths.get(ea, 0)


class _FakeStrwinsetup:
    def __init__(self) -> None:
        self.strtypes = [0x55]
        self.minlen = 5
        self.display_only_existing_strings = False
        self.only_7bit = True
        self.ignore_heads = True


class _FakeStringInfo:
    def __init__(self) -> None:
        self.ea = 0
        self.length = 0
        self.type = 0


class _FakeIdaStrlist:
    def __init__(self, items: dict[int, tuple[int, int, bytes]]) -> None:
        self._items = items
        self.options = _FakeStrwinsetup()
        self.build_calls = 0

    def get_strlist_options(self) -> _FakeStrwinsetup:
        return self.options

    @staticmethod
    def string_info_t() -> _FakeStringInfo:
        return _FakeStringInfo()

    def build_strlist(self) -> None:
        self.build_calls += 1

    def get_strlist_qty(self) -> int:
        return len(self._items)

    def get_strlist_item(self, info: _FakeStringInfo, index: int) -> bool:
        try:
            ea = sorted(self._items)[index]
        except IndexError:
            return False
        strtype, length, _text = self._items[ea]
        info.ea = ea
        info.length = length
        info.type = strtype
        return True


class _FakeIdaIda:
    @staticmethod
    def inf_get_min_ea() -> int:
        return 0x1000

    @staticmethod
    def inf_get_max_ea() -> int:
        return 0x2000


class _FakeIdaApi:
    BADADDR = -1

    def __init__(self, input_path: str = "/tmp/tiny") -> None:
        self._input_path = input_path

    def get_input_file_path(self) -> str:
        return self._input_path


class _FakeRuntime(IdaRuntime):
    def __init__(
        self,
        *,
        items: dict[int, tuple[int, int, bytes]] | None = None,
        scan_lengths: dict[int, int] | None = None,
        input_path: str = "/tmp/tiny",
    ) -> None:
        super().__init__()
        self._items = {} if items is None else items
        self._segment_ranges = (SegmentRange(name="__TEXT:__cstring", start_ea=0x1000, end_ea=0x2000),)
        self._ida_strlist = _FakeIdaStrlist(self._items)
        self._mods = {
            "ida_bytes": _FakeIdaBytes(self._items, scan_lengths=scan_lengths),
            "ida_ida": _FakeIdaIda(),
            "idaapi": _FakeIdaApi(input_path),
            "ida_strlist": self._ida_strlist,
            "ida_nalt": type(
                "FakeIdaNalt",
                (),
                {
                    "STRTYPE_TERMCHR": 7,
                    "STRTYPE_C": 0,
                },
            )(),
        }

    def mod(self, name: str):
        return self._mods[name]

    @staticmethod
    def resolve_address(identifier: str) -> int:
        return int(identifier, 0)

    def resolve_segment_ranges(
        self,
        selector: str,
        *,
        start: str | None = None,
        end: str | None = None,
        require_bounds: bool = False,
        missing_message: str = "range requires both start and end addresses",
    ) -> tuple[SegmentRange, ...]:
        assert selector == "__TEXT"
        if require_bounds and (start is None or end is None):
            raise IdaOperationError(missing_message)
        range_start = self._segment_ranges[0].start_ea if start is None else int(start, 0)
        range_end = self._segment_ranges[-1].end_ea if end is None else int(end, 0)
        if range_end <= range_start:
            raise IdaOperationError("range end must be greater than the start")
        return tuple(
            SegmentRange(
                name=item.name,
                start_ea=max(item.start_ea, range_start),
                end_ea=min(item.end_ea, range_end),
            )
            for item in self._segment_ranges
            if min(item.end_ea, range_end) > max(item.start_ea, range_start)
        )


def test_op_strings_lists_defined_strings_without_global_string_list() -> None:
    runtime = _FakeRuntime(
        items={
            0x1010: (7, 5, b"alpha"),
            0x1020: (0, 10, b"Tiny token"),
        }
    )

    rows = _op_strings(runtime, {"query": "tiny", "segment": "__TEXT"})

    assert rows == [{"address": "0x1020", "text": "Tiny token"}]
    assert runtime._ida_strlist.build_calls == 2
    assert runtime._ida_strlist.options.strtypes == [0x55]
    assert runtime._ida_strlist.options.minlen == 5
    assert runtime._ida_strlist.options.display_only_existing_strings is False
    assert runtime._ida_strlist.options.only_7bit is True
    assert runtime._ida_strlist.options.ignore_heads is True


def test_op_strings_includes_termchr_string_literals() -> None:
    runtime = _FakeRuntime(
        items={
            0x1010: (7, 9, b"term text"),
        }
    )

    rows = _op_strings(runtime, {"query": "term", "segment": "__TEXT"})

    assert rows == [{"address": "0x1010", "text": "term text"}]


def test_op_strings_returns_empty_list_when_no_matches_are_found() -> None:
    runtime = _FakeRuntime(
        items={
            0x1010: (0, 5, b"alpha"),
        }
    )

    rows = _op_strings(runtime, {"query": "missing", "segment": "__TEXT"})

    assert rows == []


def test_op_strings_scan_walks_addresses_and_finds_strings() -> None:
    runtime = _FakeRuntime(
        items={
            0x1008: (0, 5, b"alpha"),
            0x1020: (0, 10, b"Tiny token"),
        },
        scan_lengths={
            0x1008: 5,
            0x1020: 10,
        },
    )

    rows = _op_strings(
        runtime,
        {
            "scan": True,
            "segment": "__TEXT",
            "start": "0x1008",
            "end": "0x102a",
            "query": "tiny",
        },
    )

    assert rows == [{"address": "0x1020", "text": "Tiny token"}]


def test_op_strings_scan_rejects_invalid_range() -> None:
    runtime = _FakeRuntime()

    with pytest.raises(IdaOperationError, match="range end must be greater than the start"):
        _op_strings(runtime, {"scan": True, "segment": "__TEXT", "start": "0x1020", "end": "0x1020"})


def test_op_strings_rejects_defined_string_listing_on_dsc() -> None:
    runtime = _FakeRuntime(
        input_path="/System/Library/dyld/dyld_shared_cache_arm64e",
        items={0x1010: (0, 5, b"alpha")},
    )

    with pytest.raises(IdaOperationError, match="defined string listing is disabled for dyld shared caches"):
        _op_strings(runtime, {"query": "alpha", "segment": "__TEXT"})

    assert runtime._ida_strlist.build_calls == 0


def test_op_strings_does_not_treat_dsc_substring_as_shared_cache() -> None:
    runtime = _FakeRuntime(
        input_path="/tmp/my_dsc_tool",
        items={0x1010: (0, 5, b"alpha")},
    )

    rows = _op_strings(runtime, {"query": "alpha", "segment": "__TEXT"})

    assert rows == [{"address": "0x1010", "text": "alpha"}]


def test_op_strings_dsc_scan_requires_bounded_range() -> None:
    runtime = _FakeRuntime(input_path="/System/Library/dyld/dyld_shared_cache_arm64e")

    with pytest.raises(IdaOperationError, match="requires both start and end addresses"):
        _op_strings(runtime, {"scan": True, "segment": "__TEXT"})


def test_op_strings_dsc_scan_rejects_large_ranges() -> None:
    runtime = _FakeRuntime(input_path="/System/Library/dyld/dyld_shared_cache_arm64e")
    runtime._segment_ranges = (SegmentRange(name="__TEXT:__cstring", start_ea=0x1000, end_ea=0x1201000),)

    with pytest.raises(IdaOperationError, match="limited to 16 MiB"):
        _op_strings(
            runtime,
            {
                "scan": True,
                "segment": "__TEXT",
                "start": "0x1000",
                "end": "0x1201000",
            },
        )


def test_string_text_returns_empty_string_when_ida_returns_none() -> None:
    runtime = _FakeRuntime(items={0x1010: (0, 5, b"alpha")})
    runtime._mods["ida_bytes"].get_strlit_contents = lambda ea, length, strtype: None

    assert search._string_text(runtime, 0x1010, 5, 0) == ""


def test_op_strings_filters_to_selected_segment_ranges() -> None:
    runtime = _FakeRuntime(
        items={
            0x1010: (0, 5, b"alpha"),
            0x2010: (0, 10, b"Tiny token"),
        }
    )
    runtime._segment_ranges = (SegmentRange(name="__TEXT:__cstring", start_ea=0x2000, end_ea=0x2100),)

    rows = _op_strings(runtime, {"query": "tiny", "segment": "__TEXT"})

    assert rows == [{"address": "0x2010", "text": "Tiny token"}]

from __future__ import annotations

from types import SimpleNamespace

import pytest

from idac.ops.base import OperationContext
from idac.ops.families.search import SearchBytesRequest, SearchMatch, _search_bytes
from idac.ops.runtime import IdaOperationError, IdaRuntime, SegmentRange


class _CompiledPattern:
    def __init__(self, pattern: str, ea: int) -> None:
        self.pattern = pattern
        self.ea = ea

    def __len__(self) -> int:
        return 1


class _CompiledBinpatVecFactory:
    def __init__(self, *, error: str | None = None) -> None:
        self.error = error
        self.calls: list[tuple[int, str, int, int]] = []

    def parse(self, ea: int, text: str, radix: int, strlit_encoding: int) -> _CompiledPattern:
        self.calls.append((ea, text, radix, strlit_encoding))
        if self.error is not None:
            raise RuntimeError(self.error)
        return _CompiledPattern(text, ea)


class _FakeIdaBytes:
    BIN_SEARCH_FORWARD = 0x1
    BIN_SEARCH_NOBREAK = 0x2
    BIN_SEARCH_NOSHOW = 0x4

    def __init__(self, *, matches: list[int] | None = None, parse_error: str | None = None) -> None:
        self.compiled_binpat_vec_t = _CompiledBinpatVecFactory(error=parse_error)
        self._matches = [] if matches is None else list(matches)
        self.bin_search_calls: list[tuple[int, int, str, int, int]] = []
        self.find_bytes_called = False

    def bin_search(self, start_ea: int, end_ea: int, compiled, flags: int) -> tuple[int, int]:
        self.bin_search_calls.append((start_ea, end_ea, compiled.pattern, compiled.ea, flags))
        for index, match in enumerate(self._matches):
            if start_ea <= match < end_ea:
                self._matches.pop(index)
                return match, 0
        return _FakeIdaApi.BADADDR, 0

    def find_bytes(self, *args, **kwargs) -> int:
        self.find_bytes_called = True
        raise AssertionError("search bytes should not call ida_bytes.find_bytes")


class _FakeIdaApi:
    BADADDR = -1


class _FakeRuntime(IdaRuntime):
    def __init__(self, ida_bytes: _FakeIdaBytes) -> None:
        super().__init__()
        self._segment_ranges = (SegmentRange(name="__TEXT:__text", start_ea=0x1000, end_ea=0x2000),)
        self._mods = {
            "ida_bytes": ida_bytes,
            "idaapi": _FakeIdaApi(),
            "ida_ida": SimpleNamespace(
                inf_get_min_ea=lambda: 0x1000,
                inf_get_max_ea=lambda: 0x2000,
            ),
        }
        self.ida_funcs = SimpleNamespace(get_func=lambda ea: None)

    def mod(self, name: str):
        return self._mods[name]

    @staticmethod
    def resolve_address(identifier: str) -> int:
        return int(identifier, 0)

    def resolve_segment_ranges(
        self,
        selector: str,
        *,
        start: str | None = None,
        end: str | None = None,
        require_bounds: bool = False,
        missing_message: str = "range requires both start and end addresses",
    ) -> tuple[SegmentRange, ...]:
        del require_bounds, missing_message
        assert selector == "__TEXT"
        range_start = self._segment_ranges[0].start_ea if start is None else int(start, 0)
        range_end = self._segment_ranges[-1].end_ea if end is None else int(end, 0)
        if range_end <= range_start:
            raise IdaOperationError("range end must be greater than the start")
        return tuple(
            SegmentRange(
                name=item.name,
                start_ea=max(item.start_ea, range_start),
                end_ea=min(item.end_ea, range_end),
            )
            for item in self._segment_ranges
            if min(item.end_ea, range_end) > max(item.start_ea, range_start)
        )


def test_search_bytes_compiles_pattern_once_and_uses_bin_search() -> None:
    ida_bytes = _FakeIdaBytes(matches=[0x1010, 0x1020])
    runtime = _FakeRuntime(ida_bytes)

    result = _search_bytes(
        OperationContext(runtime=runtime),
        SearchBytesRequest(pattern="aa bb", segment="__TEXT", start="0x1000", end="0x1030", limit=2),
    )

    assert result.results == (
        SearchMatch(address="0x1010"),
        SearchMatch(address="0x1020"),
    )
    assert ida_bytes.compiled_binpat_vec_t.calls == [(0x1000, "aa bb", 16, -1)]
    assert [call[:4] for call in ida_bytes.bin_search_calls] == [
        (0x1000, 0x1030, "aa bb", 0x1000),
        (0x1011, 0x1030, "aa bb", 0x1000),
        (0x1021, 0x1030, "aa bb", 0x1000),
    ]
    assert ida_bytes.find_bytes_called is False


def test_search_bytes_reports_invalid_pattern_as_user_error() -> None:
    ida_bytes = _FakeIdaBytes(parse_error="Could not parse pattern: bad digit")
    runtime = _FakeRuntime(ida_bytes)

    with pytest.raises(IdaOperationError, match="invalid byte pattern: bad digit"):
        _search_bytes(
            OperationContext(runtime=runtime),
            SearchBytesRequest(pattern="zz", segment="__TEXT", start="0x1000", end="0x1030", limit=5),
        )

    assert ida_bytes.bin_search_calls == []
    assert ida_bytes.find_bytes_called is False


def test_search_bytes_returns_empty_results_when_no_matches_found() -> None:
    ida_bytes = _FakeIdaBytes(matches=[])
    runtime = _FakeRuntime(ida_bytes)

    result = _search_bytes(
        OperationContext(runtime=runtime),
        SearchBytesRequest(pattern="aa bb", segment="__TEXT", start="0x1000", end="0x1030", limit=5),
    )

    assert result.results == ()
    assert result.truncated is False
    assert ida_bytes.find_bytes_called is False


def test_search_bytes_marks_results_truncated_when_limit_is_hit() -> None:
    ida_bytes = _FakeIdaBytes(matches=[0x1010, 0x1020])
    runtime = _FakeRuntime(ida_bytes)

    result = _search_bytes(
        OperationContext(runtime=runtime),
        SearchBytesRequest(pattern="aa bb", segment="__TEXT", start="0x1000", end="0x1030", limit=1),
    )

    assert result.results == (SearchMatch(address="0x1010"),)
    assert result.truncated is True
    assert ida_bytes.find_bytes_called is False


def test_search_bytes_walks_each_matching_segment_range() -> None:
    ida_bytes = _FakeIdaBytes(matches=[0x1010, 0x2018])
    runtime = _FakeRuntime(ida_bytes)
    runtime._segment_ranges = (
        SegmentRange(name="__TEXT:__text", start_ea=0x1000, end_ea=0x1030),
        SegmentRange(name="__TEXT:__stubs", start_ea=0x2000, end_ea=0x2030),
    )

    result = _search_bytes(
        OperationContext(runtime=runtime),
        SearchBytesRequest(pattern="aa bb", segment="__TEXT", start=None, end=None, limit=10),
    )

    assert result.results == (
        SearchMatch(address="0x1010"),
        SearchMatch(address="0x2018"),
    )
    assert [call[:2] for call in ida_bytes.bin_search_calls] == [
        (0x1000, 0x1030),
        (0x1011, 0x1030),
        (0x2000, 0x2030),
        (0x2019, 0x2030),
    ]

from __future__ import annotations

from dataclasses import fields, is_dataclass
from typing import Any

JsonScalar = None | bool | int | float | str
JsonValue = JsonScalar | list["JsonValue"] | dict[str, "JsonValue"]


def payload_from_model(value: Any) -> JsonValue:
    if is_dataclass(value) and not isinstance(value, type):
        return {
            (field.name[:-1] if field.name.endswith("_") else field.name): payload_from_model(
                getattr(value, field.name)
            )
            for field in fields(value)
        }
    if isinstance(value, (list, tuple)):
        return [payload_from_model(item) for item in value]
    if isinstance(value, dict):
        return {str(key): payload_from_model(item) for key, item in value.items()}
    return value


__all__ = ["JsonScalar", "JsonValue", "payload_from_model"]

from __future__ import annotations

import contextlib
import os
from collections.abc import Mapping
from dataclasses import dataclass
from typing import Any

from ..base import OperationContext, OperationSpec
from ..helpers.matching import pattern_from_params, text_matches
from ..helpers.params import optional_param_int, optional_str, require_str
from ..runtime import IdaOperationError, IdaRuntime, SegmentRange

MEBIBYTE = 1024 * 1024
MAX_DSC_STRING_SCAN_BYTES = 16 * MEBIBYTE


@dataclass(frozen=True)
class SearchBytesRequest:
    pattern: str
    segment: str
    start: str | None
    end: str | None
    limit: int


@dataclass(frozen=True)
class SearchMatch:
    address: str


@dataclass(frozen=True)
class SearchMatchInFunction:
    address: str
    function: str


@dataclass(frozen=True)
class SearchBytesResult:
    pattern: str
    segment: str
    start: str
    end: str
    limit: int
    truncated: bool
    ranges: tuple[SearchScopeRange, ...]
    results: tuple[SearchMatch | SearchMatchInFunction, ...]


@dataclass(frozen=True)
class XrefsRequest:
    identifier: str


@dataclass(frozen=True)
class XrefRow:
    from_: str
    to: str
    type: str
    kind: str
    user: bool
    function: str | None = None


@dataclass(frozen=True)
class StringsRequest:
    pattern: str
    glob: bool
    regex: bool
    ignore_case: bool
    scan: bool
    segment: str
    start: str | None
    end: str | None


@dataclass(frozen=True)
class StringRow:
    address: str
    text: str


@dataclass(frozen=True)
class SearchScopeRange:
    name: str
    start: str
    end: str


@dataclass(frozen=True)
class ImportEntry:
    address: str
    name: str
    ordinal: int


@dataclass(frozen=True)
class ImportModule:
    module: str
    entries: tuple[ImportEntry, ...]


def _require_identifier(params: Mapping[str, Any], *, key: str = "identifier") -> str:
    return require_str(params.get(key), field="address or identifier")


def _require_segment_selector(params: Mapping[str, Any]) -> str:
    return require_str(params.get("segment"), field="segment selector")


def _parse_search_bytes(params: Mapping[str, Any]) -> SearchBytesRequest:
    pattern = require_str(params.get("pattern"), field="byte pattern")
    segment = _require_segment_selector(params)
    start = optional_str(params.get("start"))
    end = optional_str(params.get("end"))
    limit = optional_param_int(params, "limit", label="search result limit", minimum=1) or 100
    return SearchBytesRequest(pattern=pattern, segment=segment, start=start, end=end, limit=limit)


def _match_row(address: int, function: str | None) -> SearchMatch | SearchMatchInFunction:
    if function:
        return SearchMatchInFunction(address=hex(address), function=function)
    return SearchMatch(address=hex(address))


def _bin_search_address(result: Any) -> int:
    if isinstance(result, tuple):
        return int(result[0])
    return int(result)


def _search_bytes_from_cursor(runtime: IdaRuntime, start: int, end: int, compiled_pattern, flags: int) -> int:
    return _bin_search_address(runtime.mod("ida_bytes").bin_search(start, end, compiled_pattern, flags))


def _has_more_search_bytes_matches(
    runtime: IdaRuntime,
    *,
    ranges: tuple[SegmentRange, ...],
    start_index: int,
    cursor: int,
    compiled_pattern,
    flags: int,
    badaddr: int,
) -> bool:
    for index in range(start_index, len(ranges)):
        scope = ranges[index]
        scope_cursor = cursor if index == start_index else scope.start_ea
        if scope_cursor >= scope.end_ea:
            continue
        match_ea = _search_bytes_from_cursor(runtime, scope_cursor, scope.end_ea, compiled_pattern, flags)
        if match_ea != badaddr:
            return True
    return False


def _search_bytes(context: OperationContext, request: SearchBytesRequest) -> SearchBytesResult:
    runtime = context.runtime
    ida_bytes = runtime.mod("ida_bytes")
    idaapi = runtime.mod("idaapi")
    ranges = runtime.resolve_segment_ranges(
        request.segment,
        start=request.start,
        end=request.end,
        require_bounds=False,
    )
    flags = ida_bytes.BIN_SEARCH_FORWARD | ida_bytes.BIN_SEARCH_NOBREAK | ida_bytes.BIN_SEARCH_NOSHOW
    compiled_pattern = runtime.compile_binpat(request.pattern, ea=ranges[0].start_ea)

    rows: list[SearchMatch | SearchMatchInFunction] = []
    truncated = False
    for index, scope in enumerate(ranges):
        cursor = scope.start_ea
        while cursor < scope.end_ea and len(rows) < request.limit:
            match_ea = _search_bytes_from_cursor(runtime, cursor, scope.end_ea, compiled_pattern, flags)
            if match_ea == idaapi.BADADDR:
                break
            func = runtime.ida_funcs.get_func(match_ea)
            function_name = None if func is None else runtime.function_name(func.start_ea)
            rows.append(_match_row(match_ea, function_name))
            cursor = match_ea + 1
        if len(rows) == request.limit:
            truncated = _has_more_search_bytes_matches(
                runtime,
                ranges=ranges,
                start_index=index,
                cursor=cursor,
                compiled_pattern=compiled_pattern,
                flags=flags,
                badaddr=idaapi.BADADDR,
            )
            break
    return SearchBytesResult(
        pattern=request.pattern,
        segment=request.segment,
        start=hex(ranges[0].start_ea),
        end=hex(ranges[-1].end_ea),
        limit=request.limit,
        truncated=truncated,
        ranges=tuple(
            SearchScopeRange(name=item.name, start=hex(item.start_ea), end=hex(item.end_ea)) for item in ranges
        ),
        results=tuple(rows),
    )


def _parse_xrefs(params: Mapping[str, Any]) -> XrefsRequest:
    return XrefsRequest(identifier=_require_identifier(params))


def _xrefs(
    context: OperationContext,
    request: XrefsRequest,
) -> tuple[XrefRow, ...]:
    runtime = context.runtime
    ea = runtime.resolve_address(request.identifier)
    rows: list[XrefRow] = []
    seen: set[tuple[str, str, str, str, bool, str | None]] = set()
    for flags in (
        runtime.ida_xref.XREF_FLOW,
        runtime.ida_xref.XREF_CODE,
        runtime.ida_xref.XREF_DATA,
    ):
        for ref in runtime.xrefs_to(ea, flags=flags):
            func = runtime.ida_funcs.get_func(ref.from_ea)
            row = XrefRow(
                from_=hex(ref.from_ea),
                to=hex(ref.to_ea),
                type=ref.type,
                kind=ref.kind,
                user=ref.user,
                function=None if func is None else runtime.function_name(func.start_ea),
            )
            key = (row.from_, row.to, row.type, row.kind, row.user, row.function)
            if key in seen:
                continue
            seen.add(key)
            rows.append(row)
    rows.sort(key=lambda item: (item.kind, item.from_))
    return tuple(rows)


def _parse_strings(params: Mapping[str, Any]) -> StringsRequest:
    pattern, glob, regex, ignore_case = pattern_from_params(params)
    segment = _require_segment_selector(params)
    start = optional_str(params.get("start"))
    end = optional_str(params.get("end"))
    return StringsRequest(
        pattern=pattern,
        glob=glob,
        regex=regex,
        ignore_case=ignore_case,
        scan=bool(params.get("scan")),
        segment=segment,
        start=start,
        end=end,
    )


def _string_text(runtime: IdaRuntime, ea: int, length: int, strtype: int) -> str:
    value = runtime.ida_bytes.get_strlit_contents(ea, length, strtype)
    if value is None:
        return ""
    return value.decode("UTF-8", "replace")


def _defined_string_rows(
    runtime: IdaRuntime,
    *,
    ranges: tuple[SegmentRange, ...],
    pattern: str,
    glob: bool,
    regex: bool,
    ignore_case: bool,
) -> tuple[StringRow, ...]:
    ida_strlist = runtime.ida_strlist
    known_types = (
        "STRTYPE_TERMCHR",
        "STRTYPE_C",
        "STRTYPE_C_16",
        "STRTYPE_C_32",
        "STRTYPE_PASCAL",
        "STRTYPE_PASCAL_16",
        "STRTYPE_PASCAL_32",
        "STRTYPE_LEN2",
        "STRTYPE_LEN2_16",
        "STRTYPE_LEN2_32",
        "STRTYPE_LEN4",
        "STRTYPE_LEN4_16",
        "STRTYPE_LEN4_32",
    )
    string_types: list[int] = []
    seen_types: set[int] = set()
    for name in known_types:
        value = getattr(runtime.ida_nalt, name, None)
        if not isinstance(value, int) or value in seen_types:
            continue
        seen_types.add(value)
        string_types.append(value)

    options = ida_strlist.get_strlist_options()
    saved_strtypes = list(options.strtypes)
    saved_minlen = int(options.minlen)
    saved_display_only_existing_strings = bool(options.display_only_existing_strings)
    saved_only_7bit = bool(options.only_7bit)
    saved_ignore_heads = bool(options.ignore_heads)

    rows: list[StringRow] = []
    try:
        options.strtypes = string_types or [runtime.ida_nalt.STRTYPE_C]
        options.minlen = 1
        options.display_only_existing_strings = True
        options.only_7bit = False
        options.ignore_heads = False
        ida_strlist.build_strlist()

        item = ida_strlist.string_info_t()
        for index in range(int(ida_strlist.get_strlist_qty())):
            if not ida_strlist.get_strlist_item(item, index):
                continue
            ea = int(item.ea)
            if not runtime.ea_in_ranges(ea, ranges):
                continue
            text = _string_text(runtime, ea, int(item.length), int(item.type))
            if text_matches(text, pattern=pattern, glob=glob, regex=regex, ignore_case=ignore_case):
                rows.append(StringRow(address=hex(ea), text=text))
    finally:
        options.strtypes = saved_strtypes
        options.minlen = saved_minlen
        options.display_only_existing_strings = saved_display_only_existing_strings
        options.only_7bit = saved_only_7bit
        options.ignore_heads = saved_ignore_heads
        ida_strlist.build_strlist()
    return tuple(rows)


def _scan_string_rows(
    runtime: IdaRuntime,
    *,
    ranges: tuple[SegmentRange, ...],
    pattern: str,
    glob: bool,
    regex: bool,
    ignore_case: bool,
) -> tuple[StringRow, ...]:
    rows: list[StringRow] = []
    for scope in ranges:
        cursor = scope.start_ea
        while cursor < scope.end_ea:
            length = runtime.ida_bytes.get_max_strlit_length(
                cursor,
                runtime.ida_nalt.STRTYPE_C,
                runtime.ida_bytes.ALOPT_IGNHEADS,
            )
            if length < 5 or (cursor + length) > scope.end_ea:
                cursor += 1
                continue
            text = _string_text(runtime, cursor, length, runtime.ida_nalt.STRTYPE_C)
            if not text:
                cursor += 1
                continue
            if not text_matches(text, pattern=pattern, glob=glob, regex=regex, ignore_case=ignore_case):
                cursor += max(length, 1)
                continue
            rows.append(StringRow(address=hex(cursor), text=text))
            cursor += max(length, 1)
    return tuple(rows)


def _input_file_basename(runtime: IdaRuntime) -> str:
    for module_name in ("idaapi", "ida_nalt"):
        with contextlib.suppress(Exception):
            module = runtime.mod(module_name)
            getter = getattr(module, "get_input_file_path", None)
            if not callable(getter):
                continue
            path = str(getter() or "").strip()
            if path:
                return os.path.basename(path)
    return ""


def _is_current_file_dsc(runtime: IdaRuntime) -> bool:
    basename = _input_file_basename(runtime).lower()
    return basename == "dyld_shared_cache" or basename.startswith("dyld_shared_cache_")


def _range_total_size(ranges: tuple[SegmentRange, ...]) -> int:
    return sum(max(0, item.end_ea - item.start_ea) for item in ranges)


def _validate_dsc_string_scan_ranges(ranges: tuple[SegmentRange, ...]) -> None:
    requested = _range_total_size(ranges)
    if requested <= MAX_DSC_STRING_SCAN_BYTES:
        return
    raise IdaOperationError(
        "dyld shared cache string scans are limited to "
        f"{MAX_DSC_STRING_SCAN_BYTES // MEBIBYTE} MiB; requested {requested // MEBIBYTE} MiB"
    )


def _strings(context: OperationContext, request: StringsRequest) -> tuple[StringRow, ...]:
    runtime = context.runtime
    is_dsc = _is_current_file_dsc(runtime)
    ranges = runtime.resolve_segment_ranges(
        request.segment,
        start=request.start,
        end=request.end,
        require_bounds=is_dsc and request.scan,
        missing_message="dyld shared cache string scan requires both start and end addresses",
    )
    if request.scan:
        if is_dsc:
            _validate_dsc_string_scan_ranges(ranges)
        return _scan_string_rows(
            runtime,
            ranges=ranges,
            pattern=request.pattern,
            glob=request.glob,
            regex=request.regex,
            ignore_case=request.ignore_case,
        )
    if is_dsc:
        raise IdaOperationError(
            "defined string listing is disabled for dyld shared caches; use "
            "`search strings --scan --segment ... --start ... --end ...` with a range of at most "
            f"{MAX_DSC_STRING_SCAN_BYTES // MEBIBYTE} MiB"
        )
    return _defined_string_rows(
        runtime,
        ranges=ranges,
        pattern=request.pattern,
        glob=request.glob,
        regex=request.regex,
        ignore_case=request.ignore_case,
    )


def _parse_imports(_params: Mapping[str, Any]) -> None:
    return None


def _imports(context: OperationContext, request: None) -> tuple[ImportModule, ...]:
    del request
    runtime = context.runtime
    modules: list[ImportModule] = []
    for index in range(runtime.ida_nalt.get_import_module_qty()):
        module_name = runtime.ida_nalt.get_import_module_name(index) or "<unnamed>"
        entries: list[ImportEntry] = []

        def imp_cb(ea: int, name: str | None, ordinal: int, entries: list[ImportEntry] = entries) -> bool:
            entries.append(
                ImportEntry(
                    address=hex(ea),
                    name=name or f"ordinal_{ordinal}",
                    ordinal=ordinal,
                )
            )
            return True

        runtime.ida_nalt.enum_import_names(index, imp_cb)
        modules.append(ImportModule(module=module_name, entries=tuple(entries)))
    return tuple(modules)


def search_operations() -> tuple[OperationSpec[Any, Any], ...]:
    return (
        OperationSpec(
            name="search_bytes",
            parse=_parse_search_bytes,
            run=_search_bytes,
        ),
        OperationSpec(
            name="xrefs",
            parse=_parse_xrefs,
            run=_xrefs,
        ),
        OperationSpec(
            name="strings",
            parse=_parse_strings,
            run=_strings,
        ),
        OperationSpec(
            name="imports",
            parse=_parse_imports,
            run=_imports,
        ),
    )


